function multiply(a, b) {

  return a * b;

}

let result = multiply(4, 5);

sections.content:
Parameters allow you to pass (send) values to a function.

Parameters are listed inside the parentheses in the function definition.

Example

function multiply(a, b) {

  return a * b;

}

let result = multiply(4, 5);

Try it Yourself »

A function can have one parameter.

Examples

function sayHello(name) {

  return "Hello " + name;

}

let greeting = sayHello("John");

Try it Yourself »

function toCelsius(fahrenheit) {

  return (5 / 9) * (fahrenheit - 32);

}

let value = toCelsius(77);

Try it Yourself »

You can add as many parameters as you want, separated by commas.

Example

function fullName(firstName, lastName) {

  return firstName + " " + lastName;

}

let name = fullName("John", "Doe");

Try it Yourself »

Accessing a function with an incorrect parameter can return an incorrect answer:

Example

function toCelsius(fahrenheit) {

   return (5/9) * (fahrenheit-32);

}

let value = toCelsius();

Try it Yourself »

ECMAScript 2015 allows function parameters to have default values.

The default value is used if no argument is provided.

Example
If y is not passed or undefined, then y = 10.

function myFunction(x, y = 10) {

 return x + y;
}
myFunction(5);

Try it Yourself »

code_examples.code:
function sayHello() {

  return "Hello World";

}

let message = sayHello();

sections.content:
When a function reaches a return statement, the function stops executing.

The value after the return keyword is sent back to the caller.

Example

function sayHello() {

  return "Hello World";

}

let message = sayHello();

Try it Yourself »

The variable message now contains "Hello World".

Most functions return the result of a calculation or an operation.

Example

function multiply(a, b) {

  return a * b;

}

let result = multiply(4, 5);

Try it Yourself »

The returned value can be used anywhere a value is expected.

You can use a function call inside another expression.

Example

function multiply(a, b) {

  return a * b;

}

let total = multiply(2, 3) * 10;

Try it Yourself »

A function can return any type of value (not only numbers).

Example

function fullName(firstName, lastName) {

  return firstName + " " + lastName;

}

let name = fullName("John", "Doe");

Try it Yourself »

Code written after a return statement will NOT be executed.

Example

function multiply(a, b) {

  return "Done";

  // Next line will never run

  return a * b;

}

let result = multiply(4, 3);

Try it Yourself »

If a function does not return a value, the return value will be undefined.

Example

function multiply(a, b) {

  let x = a * b;

}

let result = multiply(4, 3);

Try it Yourself »

The value of result is undefined.

You can use return to stop a function early, based on a condition.

Example

function checkAge(age) {

  if (age < 18) {

    return "Too young";

  }

  return "Access granted";

}

Try it Yourself »

Returned function values are often used to update HTML content.

Example

<p id="demo"></p>

<script>

function toCelsius(farenheit) {

  return (5 / 9) * (farenheit - 32);

}

document.getElementById("demo").innerHTML = toCelsius(77);

</script>

Try it Yourself »

code_examples.code:
function multiply(a, b) {

  return a * b;

}

let result = multiply(4, 5);

function toCelsius(fahrenheit) {

   return (5/9) * (fahrenheit-32);

}

let value = toCelsius("John");

function myFunction(x, y) {

   if (y === undefined) {

    y = 2;

   }

}

sections.content:
JavaScript functions have a built-in object called the arguments 
object.

The argument object contains an array of the arguments used when the function 
was called (invoked).

This way you can simply use a function to find (for instance) the highest 
value in a list of numbers:

Example

x = findMax(1, 123, 500, 115, 44, 88);

function findMax() {

  let max = -Infinity;

   for (let i = 0; i < arguments.length; i++) {

     if (arguments[i] > max) {

      max = arguments[i];

     }

   }

   return max;

}

Try it Yourself »

Or create a function to sum all input values:

Example

x = sumAll(1, 123, 500, 115, 44, 88);

function sumAll() {

  let sum = 0;

   for (let i = 0; i < arguments.length; i++) {

    sum += arguments[i];

   }

   return sum;

}

Try it Yourself »

If a function is called with too many arguments (more than declared),
these arguments can be reached using the arguments object.

Arguments are assigned to parameters in the order they appear.

Example

function subtract(a, b) {

  return a - b;

}

let x1 = subtract(10, 5);

let x2 = subtract(5, 10);

Try it Yourself »

The two calls above return different results because the order is different.

Arguments do not have to be values. They can also be variables.

 Example

 let x = 5;

 let y = 6;

 function multiply(a, b) {

   return a * b;

 }

 multiply(x, y);

Incorrect arguments can return incorrect answers:

Example

function toCelsius(fahrenheit) {

   return (5/9) * (fahrenheit-32);

}

let value = toCelsius("John");

Try it Yourself »

If a function is called with fewer arguments than parameters, the missing values become undefined.

 Example

 function multiply(a, b) {

   return a * b;

 }

 multiply(4);

In the example above, b is undefined, so the result is NaN.

A JavaScript function does not perform any checking on parameter values (arguments).

If a function is called with missing arguments (less than declared), the missing values are set to
undefined.

Sometimes this is acceptable, but sometimes it is better to assign a default 
value to the parameter:

Example

function myFunction(x, y) {

   if (y === undefined) {

    y = 2;

   }

}

Try it Yourself »

ECMAScript 2015 allows function parameters to have default values.

You can now set a default value for a parameter.

The default value is used if no argument is provided.

Example
If y is not passed or undefined, then y = 10.

function myFunction(x, y = 10) {

 return x + y;
}
myFunction(5);

Try it Yourself »

The rest parameter (...) allows a function to treat an indefinite number of arguments as an array:

Example

function sum(...args) {

  let sum = 0;

  for (let arg of args) sum += arg;

  return sum;

}

let x = sum(4, 9, 16, 25, 29, 100, 66, 77);

Try it Yourself »

code_examples.code:
Example

const add = function(a, b) {

  return a + b;

};

Example

 function run(fn) {

   return fn();

 }

 const sayHello = function() {

   return "Hello";

 };

 run(sayHello);

const sayHello = function() {

  return "Hello World";

};

sayHello();

sections.content:
A function expression is a function stored in a variable.

// Standard Function

function multiply(a, b) {

  return a * b;

}

// Function Expression

const multiply = function(a, b) {

  return a * b;

};

Example

const multiply = function (a, b) {return a * b};

Try it Yourself »

After a function expression has been stored in a variable, the variable can be used as a function:

Example

let z = multiply(4, 3);

Try it Yourself »

A function expression is a JavaScript statement.

That is why it usually ends with a semicolon.

Example

const add = function(a, b) {

  return a + b;

};

Because a function expression is stored in a variable, it can be used like a value.

This is useful when passing functions to other functions (callbacks).

A function expression can be assigned to a variable, passed as an argument to another function,
or returned from a function.

 Example

 function run(fn) {

   return fn();

 }

 const sayHello = function() {

   return "Hello";

 };

 run(sayHello);

A function declaration (or simply a function) is defined using:

The function keyword

A function name

Parameters in parentheses

A code block brackets

function add(a, b) {return a + b;}

A function expression is defined using:

The function keyword

Parameters in parentheses

A code block brackets

const add = function(a, b) {return a + b;};

Example

const sayHello = function() {

  return "Hello World";

};

sayHello();

Try it Yourself »

The function above is stored in the variable sayHello.

To run it, you call sayHello().

code_examples.code:
Example

 const add = (a, b) => {

   return a + b;

 };

Example

 const person = {

   name: "John",

   greet: function() {

     return this.name;

   }

 };

Example

 const person = {

   name: "John",

   greet: () => {

     return this.name;

   }

 };

sections.content:
An arrow function uses the => symbol.

An arrow function is always written as a function expression.

 Example

 const add = (a, b) => {

   return a + b;

 };

This arrow function does the same thing as a regular function expression.

If a function has only one parameter, you can omit the parentheses:

With Parantheses

const square = (x) => x * x;

Try it Yourself »
Without Parantheses

const square = x => x * x;

Try it Yourself »

With Parantheses

const hello = (val) => "Hello " + val;

Try it Yourself »
Without Parantheses

const hello = val => "Hello " + val;

Try it Yourself »

If there are no parameters, parentheses are required.

With Arrow Function:

const hello = () => "Hello World!";

Try it Yourself »

You can only omit the return keyword and the curly brackets if the function is a single
statement. Because of this, it might be a good habit to always keep them:

Example

// This will return undefined

const myFunction = (x, y) => { x * y };

// This will return undefined

const myFunction = (x, y) => return x * y;

// This will return the expected result

const myFunction = (x, y) => { return x * y };

Try it Yourself »

Arrow functions do not have their own this value.

They inherit this from the surrounding code.

 Example

 const person = {

   name: "John",

   greet: function() {

     return this.name;

   }

 };

Using an arrow function as a method often gives unexpected results.

 Example

 const person = {

   name: "John",

   greet: () => {

     return this.name;

   }

 };

In this case, this does not refer to the person object.

code_examples.code:
function sayHello() {

  return "Hello World";

}

let text = sayHello();

sections.content:
What is returned in the text variable?

function sayHello() {

  return "Hello World";

}

let text = sayHello();

 A. sayHello

 B. Hello World

 C. undefined

Which line calls the function?

function test() {

  return 5;

}

let x = test;

let y = test();

 A. function test() { }

 B. let x = test;

 C. let y = test();

In the function below, what are a and b?

function multiply(a, b) {

  return a * b;

}

 A. Arguments

 B. Parameters

 C. Return values

What is the value of x in this example?

function add(a, b) {

  return a + b;

}

x = add(2, 3) * 10;

 A. 5

 B. 10

 C. 50

Which arrow function is correct?

 A. const add = (a, b) => return a + b;

 B. const add = a, b => a + b;

 C. const add = (a, b) => a + b;

What does this refer to inside an object method?

const person = {

  name: "John",

  getName: function() {

    return this.name;

  }

};

 A. The function itself

 B. The global object

 C. The object that owns the method

Why does this code not work as expected?

const person = {

  name: "John",

  greet: () => this.name

};

 A. Arrow functions cannot return values

 B. Arrow functions do not have their own this

 C. The object syntax is wrong

code_examples.code:
// Call a Timeout

setTimeout(myFunction, 3000);

// The callback function

function myFunction() {

  myDisplayer("Hello!");

}

setTimeout(function() {

  myDisplayer("Hello!");

}, 3000);

setInterval(showTime, 1000);

function showTime() {

  const date = new Date();

  myDisplayer(date.toLocaleTimeString());

}

sections.content:
The setTimeout() function schedules a function to run once after a delay.

Syntax

setTimeout(function, milliseconds);

The first argument is the function to run.

The second argument is the delay in milliseconds.

One second is 1000 milliseconds.

Example
Display a message after three seconds:

// Call a Timeout

setTimeout(myFunction, 3000);

// The callback function

function myFunction() {

  myDisplayer("Hello!");

}

Try it Yourself »

Note
When a function name is passed to a function, it is called a callback function.

You can pass an anonymous function to setTimeout().

Example

setTimeout(function() {

  myDisplayer("Hello!");

}, 3000);

Try it Yourself »

The specified delay is the earliest time the callback can run.

The callback may run later if JavaScript is busy.

Example

setTimeout(function() {

  myDisplayer("Timer finished");

}, 1000);

let i = 4e9;

while (--i > 0);

Try it Yourself »

The timer delay is one second.

However, the callback cannot run until the loop has finished.

Timers do not interrupt running JavaScript.

A long-running function can delay timer callbacks and make the page unresponsive.

The setTimeout() function returns a timer identifier.

Pass the identifier to clearTimeout() to cancel the timer.

Syntax

clearTimeout(timerId);

Example

<button onclick="startTimer()">Start Timer</button>

<button onclick="stopTimer()">Stop Timer</button>

<p id="demo"></p>

let timer;

function startTimer() {

  timer = setTimeout(function() {

    document.getElementById("demo").innerHTML = "Finished";

  }, 5000);

}

function stopTimer() {

  clearTimeout(timer);

  document.getElementById("demo").innerHTML = "Timer stopped";

}

Try it Yourself »

The setInterval() function runs a callback function repeatedly.

Syntax

setInterval(function, milliseconds);

The callback function is called repeatedly with (at least) the specified delay in between.

Example
Display the current time every second:

setInterval(showTime, 1000);

function showTime() {

  const date = new Date();

  myDisplayer(date.toLocaleTimeString());

}

Try it Yourself »

The setInterval() function returns an interval identifier.

Pass the identifier to clearInterval() to stop the interval.

Syntax

clearInterval(intervalId);

Example

<button onclick="startClock()">Start Clock</button>

<button onclick="stopClock()">Stop Clock</button>

<p id="demo"></p>

let timer;

function startClock() {

  if (!timer) {

    timer = setInterval(showTime, 1000);

  }

}

function showTime() {

  const date = new Date();

  document.getElementById("demo").innerHTML = date.toLocaleTimeString();

}

function stopClock() {

  clearInterval(timer);

  timer = undefined;

}

Try it Yourself »

Arguments passed to setTimeout() or setInterval() are passed to the callback function.

Example

setTimeout(showMessage, 2000, "Hello", "John");

function showMessage(greeting, name) {

  document.getElementById("demo").innerHTML = greeting + " " + name;

}

Try it Yourself »

You can create a repeating timer by calling setTimeout() again after each task finishes.

Example

function repeat() {

  myDisplayer("Hello");

  setTimeout(repeat, 1000);

}

repeat();

Try it Yourself »

With repeated setTimeout(), the next delay begins after the current callback has finished.

With setInterval(), the interval continues to schedule callbacks at regular intervals.

Repeated setTimeout() is useful when one task must finish before the next delay begins.

Example

<button onclick="startCountdown()">Start Countdown</button>

<p id="demo"></p>

let timer;

function startCountdown() {

  clearInterval(timer);

  let count = 10;

  myDisplayer(count);

  timer = setInterval(function() {

    count--;

    myDisplayer(count);

    if (count === 0) {

      clearInterval(timer);

      myDisplayer("Finished!");

    }

  }, 1000);

}

Try it Yourself »

Timer functions can accept strings, but strings should not be used as JavaScript code.

Not Recommended

setTimeout("myFunction()", 1000);

Recommended

setTimeout(myFunction, 1000);

Passing a function is safer, clearer, and easier to debug.

The browser manages the waiting period outside the current JavaScript task.

However, the timer callback still runs on the main JavaScript thread.

A long-running timer callback can therefore freeze the page.

Example

setTimeout(function() {

  let i = 4e9;

  while (--i > 0);

  document.getElementById("demo").innerHTML = "Finished";

}, 1000);

Try it Yourself »

The timer delays when the callback starts.

It does not prevent the callback from blocking the page after it starts.

Calling the Function Immediately

setTimeout(myFunction(), 1000);

Remove the parentheses when passing the function:

setTimeout(myFunction, 1000);

Forgetting the Timer Identifier

Save the returned identifier if the timer must be canceled later.

const timer = setTimeout(myFunction, 1000);

clearTimeout(timer);

Starting Multiple Intervals

Starting an interval more than once creates multiple repeating timers.

if (!timer) {

  timer = setInterval(myFunction, 1000);

}

Expecting Exact Timing

Timer delays are not exact schedules.

Callbacks run only when JavaScript is ready.

Forgetting to Stop an Interval

An interval continues until it is stopped or the page is closed.

clearInterval(timer);

Timers can be used to change images automatically.

This example displays a new image every three seconds.

Example

<img id="slide" src="img_nature.jpg" style="width:100%;max-width:600px">

<button onclick="startSlides()">Start</button>

<button onclick="stopSlides()">Stop</button>

const images = [

  "img_nature.jpg",

  "img_snowtops.jpg",

  "img_mountains.jpg"

];

let index = 0;

let timer;

function showNextSlide() {

  index = (index + 1) % images.length;

  document.getElementById("slide").src = images[index];

}

function startSlides() {

  if (!timer) {

    timer = setInterval(showNextSlide, 3000);

  }

}

function stopSlides() {

  clearInterval(timer);

  timer = undefined;

}

Try it Yourself »

The remainder operator % returns the index to zero after the last image.

The test in startSlides() prevents several intervals from running at the same time.

code_examples.code:
const car = {

   type: "Fiat",

   model: "500",

   color: "white"

 };

sections.content:
An object literal "literally" describes an object using a concise syntax with zero or more
key:value pairs inside curly braces to describe all the object properties:

{firstName:"John", lastName:"Doe", age:50, eyeColor:"blue"}

An object literal is the simplest and most common way to define a JavaScript object.

All the examples below, create the same JavaScript object:

Example 1

// Create an Object

const person = {firstName:"John", lastName:"Doe", age:50, eyeColor:"blue"};

Try it Yourself »

Spaces and line breaks are not important. An object literal can span multiple lines: 

Example 2

// Create an Object

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  eyeColor: "blue"

};

Try it Yourself »

You can also create an empty object, and add the properties later:

Example 3

// Create an Object

const person = {};

// Add Properties

person.firstName = "John";

person.lastName = "Doe";

person.age = 50;

person.eyeColor = "blue";

Try it Yourself »

You should declare objects with the const keyword.

Example 4
Create a new JavaScript object using new Object():

// Create an Object

const person = new Object({

  firstName: "John",

  lastName: "Doe",

  age: 50,

  eyeColor: "blue"

});

Try it Yourself »

There is no need to use new Object().

For readability, simplicity and speed, use an object literal instead.

Objects can also have methods.

Object methods are actions that can be performed on objects.

Object methods are function definitions stored as property values:

Example

const person = {

   firstName: "John",

   lastName : "Doe",

   age      : 50,

   fullName : function() {

    return this.firstName + " " + this.lastName;
  }

};

Try it Yourself »

PropertyProperty Value

firstNameJohn

lastNameDoe

age50

fullName
function() {return this.firstName + " " + this.lastName;}

In an object method, this refers to the object.

In the example above, this refers to the person object.

You can access object properties in these ways:

Dot notation

Bracket notation

Expression

Examples

// objectName.property

let age = person.age;

//objectName["property"]

let age = person["age"];

//objectName[expression]

let age = person[x];

Dot Notation

objectName.propertyName

person.firstname + " is " + person.age;

Try it Yourself »

Bracket Notation

objectName["propertyName"]

person["firstname"] + " is " + person["age"];

Try it Yourself »

In general, dot notation is preferred for readability and simplicity.

Bracket notation is necessary in some cases:

The property name is stored in a variable:

person[myVariable] 

The property name is not a valid identifier:

person["last-name"]

Bracket notation is useful when the property name is stored in a variable:

Example

let n1 = "firstName";

let n2 = "lastName";

let name = person[n2] + " " + person[n2]; 

Try it Yourself »

The delete keyword deletes a property from an object:

Examples

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

};

delete person.age;

Try it Yourself »

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

};

delete person["age"];

Try it Yourself »

The delete keyword deletes both the value and the property.

After deleting, the property is removed. Accessing it will return undefined.

Use the in operator to check if a property exists in an object:

Example

const person = {

  firstName: "John",

  lastName: "Doe"

};

let result = ("firstName" in person);

Try it Yourself »

Property values in an object can be other objects:

Example

myObj = {

  name:"John",
  age:30,

 myCars: {
    car1:"Ford",

 car2:"BMW",
    car3:"Fiat"

   }
}

You can access nested objects using the dot notation or the bracket notation:

Examples

myObj.myCars.car2;

Try it Yourself » 

myObj.myCars["car2"];

Try it Yourself » 

myObj["myCars"]["car2"];

Try it Yourself » 

let p1 = "myCars";

let p2 = "car2";

myObj[p1][p2];

Try it Yourself »

code_examples.code:
const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  fullName: function() {

    return this.firstName + " " + 
this.lastName;
  }

};

sections.content:
Methods are actions that can be performed on objects.

Methods are functions stored as property values.

Example

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  fullName: function() {

    return this.firstName + " " + 
this.lastName;
  }

};

Try it Yourself »

 Property
 Value

 firstName
 John

 lastName
 Doe

 age
 50

 fullName
 function() {

  return this.firstName + " " + this.lastName;

}

In an object method, this refers to the object.

Example 1

const person = {

  firstName: "John",

  lastName: "Doe",

  id: 5566,

  getId: function() {

    return this.id;

  }

};

let number = person.getId();

Try it Yourself »

In the example above, this refers to the person object.

this.id means the id property of the person object.

Example 2

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  fullName: function() {

    return this.firstName + " " + 
this.lastName;
  }

};

Try it Yourself »

In the example above, this refers to the person object.

this.firstName means the firstName property of the person object.

this.lastName means the lastName property of the person object.

You can add a method to an object by assigning a function to a property:

Example

// Assign person.name to a function

person.name = function () {
  return this.firstName + " " + this.lastName;
};

Try it Yourself »

In the example above, person.name is a property with a function assigned to it.

This example uses the JavaScript toUpperCase() method to convert a text 
to uppercase:

Example

person.name = function () {

  return (this.firstName + " " + this.lastName).toUpperCase();

};

Try it Yourself »

code_examples.code:
const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  fullName: function() {

    return this.firstName + " " + this.lastName;

  }

};

sections.content:
When used inside an object method, this refers to the object.

Example

const person = {

  firstName: "John",

  lastName: "Doe",

  age: 50,

  fullName: function() {

    return this.firstName + " " + this.lastName;

  }

};

Try it Yourself »

In the example above:

 this.firstName refers to the firstName property of the person object

 this.lastName refers to the lastName property of the person object

The this keyword makes it possible to use the same method with different objects.

 Example

 const person1 = {

   name: "John",

   hello: function() {

     return "Hello " + this.name;

   }

 };

 const person2 = {

   name: "Anna",

   hello: function() {

     return "Hello " + this.name;

   }

 };

 document.getElementById("demo").innerHTML = person1.hello();

Try it Yourself »

In a regular function, this also refers to the global object.

 Example

 function myFunction() {

   return this;

 }

 document.getElementById("demo").innerHTML = myFunction();

 Try it Yourself »

code_examples.code:
// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

let text = person;

sections.content:
Displaying a JavaScript object will output [object Object].

Example

// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

let text = person;

Try it Yourself »

The properties of an object can be added in a string:

Example

// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

// Add Properties

let text = person.name + "," + person.age + "," + person.city;

Try it Yourself »

The properties of an object can be collected in a loop:

Example

// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

// Build a Text

let text = "";

for (let x in person) {

  text += person[x] + " ";

};

Try it Yourself »

You must use person[x] in the loop.

person.x will not work (Because x is the loop variable).

Object.values() creates an array from the property values:

// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

// Create an Array

const myArray = Object.values(person);

// Stringify the Array

let text = myArray.toString();

Try it Yourself »

Object.entries() makes it simple to use objects in loops:

Example

const fruits = {Bananas:300, Oranges:200, Apples:500};

let text = "";

for (let [fruit, value] of Object.entries(fruits)) {

  text += fruit + ": " + value + "<br>";

}

Try it Yourself »

JavaScript objects can be converted to a string with JSON method
JSON.stringify().

JSON.stringify() is included in JavaScript and supported in all browsers.

The result will be a string written in JSON notation:

{"name":"John","age":50,"city":"New York"}

Example

// Create an Object

const person = {

  name: "John",

  age: 30,

  city: "New York"

};

// Stringify Object

let text = JSON.stringify(person);

Try it Yourself »

