"November", "December"];

const d = new Date("2021-03-25");

let month = months[d.getMonth()];

Try it Yourself »

const months = ["January", "February", "March", "April", "May",
"June", "July", "August", "September", "October",
"November", "December"];

const d = new Date();

let month = months[d.getMonth()];

