const person = {name: "John", lastname: "Doe"};

let answer = Reflect.has(person, "name");

// Create an Object

const user = { name: "Jan", age: 40 };

// Create a Proxy

const proxy = new Proxy(user, {

  set(target, property, value) {

    log(property + ": " + value);

    // safe forwarding

    return Reflect.set(target, property, value);

