code_examples.code:
// Create an ArrayBuffer

const myBuf = new ArrayBuffer(16);

// Get the length in bytes

let len = myBuf.byteLength;

sections.content:
Use new ArrayBuffer() to create a new ArrayBuffer.

Example
Create a 16-byte ArrayBuffer:

// Create an ArrayBuffer

const myBuf = new ArrayBuffer(16);

// Get the length in bytes

let len = myBuf.byteLength;

Try it Yourself »

The size of an ArrayBuffer is specified in bytes.

The byteLength property represents the size.

Once created, the size can not be changed.

Example
Each Uint8 uses 1 byte.

// Create an ArrayBuffer

const myBuf = new ArrayBuffer(8);

// Create a Uint8Array view

const view = new Uint8Array(myBuf);

// Write max 8 values

view[0] = 10;

view[2] = 128;

view[1] = 255;

// Read values

let v0 = view[0];

let v1 = view[1];

let v2 = view[2];

Try it Yourself »

Example

Each Int32 uses 4 bytes.

// Create an ArrayBuffer

const myBuf = new ArrayBuffer(12);

// Create an Int32Array view

const view = new Int32Array(myBuf);

// 12 bytes = max 3 Int32 values

view[0] = 100000;

view[1] = 200000;

view[2] = 300000;

// Read values

let v0 = view[0];

let v1 = view[1];

let v2 = view[2];

Try it Yourself »

A DataView is a more flexible view for an ArrayBuffer.

A DataView lets you read and write values of different types (Int8, Uint16, Float32, etc.).

A DataView also lets you read and write values at any byte offset.

Example: Reading and Writing with DataView

// Create an ArrayBuffer

const myBuf = new ArrayBuffer(8);

// Create a DataView

const view = new DataView(myBuf);

// Write a 32-bit integer at byte offset 0

view.setInt32(0, 123456);

// Write a 16-bit integer at byte offset 4

view.setInt16(4, 32000);

// Read the values

let v1 view.getInt32(0);

let v2 = view.getInt16(4);

Try it Yourself »

The DataView methods have an optional littleEndian parameter (true/false)
to control the byte order.

You can make a copy of a part of an ArrayBuffer using
the slice() method. It returns a new ArrayBuffer
with bytes from the specified range.

Example: ArrayBuffer.slice()

// Create an ArrayBuffer

const myBuf = new ArrayBuffer(8);

// Create a Uint8Array

const view = new Uint8Array(myBuf);

// Fill with values 0 to 7

for (let i = 0; i < view.length; i++) {

  view[i] = i;

}

// Create a copy of bytes from 2 to 5 (not including 5)

const sliced = myBuf.slice(2, 5);

const slicedView = new Uint8Array(sliced);

Try it Yourself »

The slice() method creates a new buffer.

The slice() method does not share memory with the original buffer.

Example
Converting a String to an ArrayBuffer (UTF-8)

function stringToArrayBuffer(str) {

  const encoder = new TextEncoder();

  return encoder.encode(str).buffer;

}

const myBuf = stringToArrayBuffer("Hello");

let len1 = myBuf.byteLength;

Try it Yourself »

Example
Converting an ArrayBuffer to a String (UTF-8)

function arrayBufferToString(buffer) {

  const decoder = new TextDecoder();

  return decoder.decode(new Uint8Array(buffer));

}

const encoder = new TextEncoder();

const myBuf = encoder.encode("Hello ArrayBuffer").buffer;

let text = arrayBufferToString(myBuf);

Try it Yourself »

An ArrayBuffer is not shared between threads by default.

To share memory between workers, JavaScript provides SharedArrayBuffer.

It behaves like ArrayBuffer, but its contents can be shared and
used with Atomics.

Example: Creating a SharedArrayBuffer

if (Window.crossOriginIsolated) {

  buffer = new SharedArrayBuffer(16);

} else {

  buffer = new ArrayBuffer(16);

}

const sharedView = new Int32Array(buffer);

buffer[0] = 42;

let numb = sharedView[0];

Try it Yourself »

Browsers may require special security headers to enable
SharedArrayBuffer (COOP/COEP).

code_examples.code:
// Create a 16 bytes ArrayBuffer

const buffer = new ArrayBuffer(16);

// Create a new DataView

const view = new DataView(buffer);

// Get lengths and offset

let len1 = buffer.byteLength);

let len2 = view.byteLength;

let off1 = view.byteOffset;

Example
getFloat64() and setFloat64()

const buffer = new ArrayBuffer(16);

const view = new DataView(buffer);

view.setFloat64(0, Math.PI);

view.setFloat64(8, Math.E);

const pi = view.getFloat64(0);

const e = view.getFloat64(8);

console.log("PI:", pi);

console.log("E:", e);

Example: Writing with Little-Endian and Big-Endian

const buffer = new ArrayBuffer(4);

const view = new DataView(buffer);

// Same number, two different byte orders:

view.setUint32(0, 0x12345678, true); // little-endian

console.log(new Uint8Array(buffer));

// Example output: Uint8Array(4) [120, 86, 52, 18] (0x78, 0x56, 0x34, 0x12)

// Overwrite with big-endian

view.setUint32(0, 0x12345678, false); // big-endian

console.log(new Uint8Array(buffer));

// Example output: Uint8Array(4) [18, 52, 86, 120] (0x12, 0x34, 0x56, 0x78)

Example: Mixed Types

const buffer = new ArrayBuffer(12);

const view = new DataView(buffer);

// Byte 0: a flag (0 or 1)

view.setUint8(0, 1);

// Bytes 1-2: a 16-bit length (little-endian)

view.setUint16(1, 500, true);

// Bytes 4-11: a 64-bit float (skip byte 3 for alignment)

view.setFloat64(4, 3.14159, true);

// Read the values back

const flag = view.getUint8(0);

const length = view.getUint16(1, true);

const value = view.getFloat64(4, true);

console.log("Flag:", flag);

console.log("Length:", length);

console.log("Value:", value);

function writeRecord(view, offset, id, score, code) {
 // id: Uint32 (4 bytes)
 view.setUint32(offset, id, true); // little-endian

 // score: Float32 (4 bytes)
 view.setFloat32(offset + 4, score, true);

 // code: 5 ASCII chars (5 bytes)
 for (let i = 0; i < 5; i++) {
 const charCode = code.charCodeAt(i) || 0;
 view.setUint8(offset + 8 + i, charCode);
 }
}

function readRecord(view, offset) {
 const id = view.getUint32(offset, true);
 const score = view.getFloat32(offset + 4, true);

 let code = "";
 for (let i = 0; i < 5; i++) {
 const charCode = view.getUint8(offset + 8 + i);
 if (charCode !== 0) {
 code += String.fromCharCode(charCode);
 }
 }

 return { id, score, code };
}

const buffer = new ArrayBuffer(13);
const view = new DataView(buffer);

writeRecord(view, 0, 123, 98.5, "HELLO");

const record = readRecord(view, 0);
console.log(record.id); // 123
console.log(record.score); // 98.5
console.log(record.code); // "HELLO"

