 sendMessage(msg: string): void;
}

const user: User = {
 name: "John",
 email: "john@example.com",
 sendMessage(msg) {
 console.log(msg);
 }
};

// IDE shows all available properties
user. // Shows: name, email, sendMessage

5. Function Parameters

TypeScript:

function greet(name: string, age: number) {
 return `${name} is ${age} years old`;
}

greet("John", 25); // OK
greet("John", "25"); // Error!

Example
interface GreetingProps {
 name: string;
 age?: number; // Optional prop
}

function Greeting({ name, age }: GreetingProps) {
 return (
 <div>
 <h1>Hello, {name}!</h1>
 {age && <p>You are {age} years old</p>}
 </div>
 );
}

function App() {
 return (
 <div>
 <Greeting name="John" age={25} />
 <Greeting name="Jane" />
 </div>
 );
}

Run Example »

Typing Hooks
How to use TypeScript with React hooks:

Example
import { useState, useEffect } from 'react';

interface User {
 id: number;
 name: string;
 email: string;
}

function UserProfile() {
 const [user, setUser] = useState<User | null>(null);
 const [loading, setLoading] = useState(false);

 useEffect(() => {
 setLoading(true);
 fetch('/api/user')
 .then(res => res.json())
 .then((data: User) => setUser(data))
 .finally(() => setLoading(false));
 }, []);

 if (loading) return <div>Loading...</div>;
 if (!user) return <div>No user found</div>;

 return (
 <div>
 <h1>{user.name}</h1>
 <p>{user.email}</p>
 </div>
 );
}

Event Handling
TypeScript helps you handle events correctly:

Example
function Form() {
 const handleSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 // Form handling logic
 };

 const handleChange = (e: React.ChangeEvent) => {
 console.log(e.target.value);
 };

 return (
 <form onSubmit={handleSubmit}>
 <input 
 type="text" 
 onChange={handleChange} 
 placeholder="Type here..."
 />
 <button type="submit">Submit</button>
 </form>
 );
}

Common Types
Frequently used TypeScript types in React:

// Props with children
interface ContainerProps {
 children: React.ReactNode;
 className?: string;
}

// Event handlers
type ButtonProps = {
 onClick: (e: React.MouseEvent) => void;
 disabled?: boolean;
}

// Style objects
interface Styles {
 color: string;
 backgroundColor?: string;
 [key: string]: string | undefined;
}

// Ref types
const inputRef = useRef<HTMLInputElement>(null);

Note: TypeScript's type inference is quite good. You don't always need to explicitly declare types when they can be inferred.

Best Practices

 Use interfaces for objects that represent a clear concept

 Use type for unions, intersections, or mapped types

 Make props optional when they have sensible defaults

 Use the built-in React types when possible

 Keep type definitions close to where they're used

