Examples for Each Feature

1. Type System

TypeScript:

// Types are explicitly declared
let name: string = "John";
let age: number = 25;
let active: boolean = true;
let numbers: number[] = [1, 2, 3];

// Type error caught at compile time
age = "25"; // Error: Type 'string' is not 
 // assignable to type 'number'

JavaScript:

// Types are inferred dynamically
let name = "John";
let age = 25;
let active = true;
let numbers = [1, 2, 3];

// No type checking
age = "25"; // Works, but might cause issues
 // later in the code

2. Error Detection

TypeScript:

interface User {
 name: string;
 email: string;
}

function sendEmail(user: User) {
 console.log(user.email);
}

// Error caught during compilation
sendEmail({ name: "John" }); // Error: missing
 // email property

JavaScript:

function sendEmail(user) {
 console.log(user.email);
}

// Error only appears when running
sendEmail({ name: "John" });
// Runtime error: Cannot read property
// 'email' of undefined

3. Object Properties

TypeScript:

interface Person {
 name: string;
 age: number;
}

const person: Person = {
 name: "John",
 age: 25
};

// Error: Property 'location' does not
// exist on type 'Person'
person.location = "NYC";

JavaScript:

const person = {
 name: "John",
 age: 25
};

// Can freely add new properties
person.location = "NYC"; // Works fine

// But might cause issues if property
// name is misspelled or used
// inconsistently

4. IDE Support

