TypeScript helps you handle events correctly:

Example
function Form() {
 const handleSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 // Form handling logic
 };

 const handleChange = (e: React.ChangeEvent) => {
 console.log(e.target.value);
 };

 return (
 <form onSubmit={handleSubmit}>
 <input 
 type="text" 
 onChange={handleChange} 
 placeholder="Type here..."
 />
 <button type="submit">Submit</button>
 </form>
 );
}

Frequently used TypeScript types in React:

// Props with children
interface ContainerProps {
 children: React.ReactNode;
 className?: string;
}

// Event handlers
type ButtonProps = {
 onClick: (e: React.MouseEvent) => void;
 disabled?: boolean;
}

// Style objects
interface Styles {
 color: string;
 backgroundColor?: string;
 [key: string]: string | undefined;
}

// Ref types
const inputRef = useRef<HTMLInputElement>(null);

Note: TypeScript's type inference is quite good. You don't always need to explicitly declare types when they can be inferred.

