 <img :src="x.imgUrl">
 <p class="pName">{{ x.name }}</p>
 </div>
</template>

<script>
export default {
 inject: ['foods']
}
</script>

<style scoped>
 div {
 margin: 10px;
 padding: 10px;
 display: inline-block;
 width: 80px;
 background-color: #28e49f47;
 border-radius: 10px;
 }
 .pName {
 text-align: center;
 }
