 animation: swirlAdded 1s reverse;
 }
 @keyframes swirlAdded {
 from {
 opacity: 0;
 rotate: 0;
 scale: 0.1;
 }
 to {
 opacity: 1;
 rotate: 360deg;
 scale: 1;
 }
 }
 #p1, #p2 {
 display: inline-block;
 padding: 10px;
 border: dashed black 1px;
 }
 #p2 {
 background-color: lightcoral;
 }
</style>

