@Component({
 selector: 'app-root',
 standalone: true,
 imports: [CommonModule],
 template: `
 <button (click)="toggle()">Toggle user</button>
 <p *ngIf="user as u; else empty">Hello {{ u.name }}!</p>
 <ng-template #empty>No user</ng-template>
 `
})
