Render a basic list with @for and expose the index:

 Example
 import { bootstrapApplication } from '@angular/platform-browser';
import { Component, signal } from '@angular/core';

@Component({
 selector: 'app-root',
 standalone: true,
 template: `
 <h3>Lists</h3>
