import { signal, computed, effect } from '@angular/core';

const count = signal(0);
const double = computed(() => count() * 2);
effect(() => console.log('count =', count()));

count.update(n => n + 1);

 Notes:

 Related: See Data Binding, Services & DI, and Change Detection.

