Sanitization Basics

 // Property binding runs the sanitizer
<img [src]="photoUrl" alt="...">
<a [href]="profileUrl">Profile</a>

 Example
 import { bootstrapApplication } from '@angular/platform-browser';
import { Component } from '@angular/core';

@Component({
 selector: 'app-root',
 standalone: true,
 template: `
 <h3>Sanitized HTML</h3>
