function divide(a: number, b: number): number {

  if (b === 0) {

    throw new Error('Division by zero');

  }

  return a / b;

}

try {

  const result = divide(10, 0);

  console.log(result);

} catch (error) {

   console.error('An error occurred:', error.message);

}

interface User {

   id: number;

   name: string;

   email: string;

 }

 // Using async/await with try/catch

 async function fetchUser(userId: number): Promise {

   try {

     const response = await fetch(`/api/users/${userId}`);

     if (!response.ok) {

       throw new Error(`HTTP error! status: ${response.status}`);

     }

     return await response.json() as User;

   } catch (error) {

     if (error instanceof Error) {

       console.error('Failed to fetch user:', error.message);

     }

     throw error; // Re-throw to allow caller to handle

   }

 }

 // Using Promise.catch() for error handling

 function fetchUserPosts(userId: number): Promise {

   return fetch(`/api/users/${userId}/posts`)

     .then(response => {

       if (!response.ok) {

         throw new Error(`HTTP error! status: ${response.status}`);

       }

       return response.json();

     })

     .catch(error => {

       console.error('Failed to fetch posts:', error);

       return []; // Return empty array as fallback

     });

 }

React Error Boundary Component
 Create an Error Boundary to catch JavaScript errors in React component trees:

 import React, { Component, ErrorInfo, ReactNode } from 'react';

 interface ErrorBoundaryProps {

   children: ReactNode;

   fallback?: ReactNode;

 }

 interface ErrorBoundaryState {

   hasError: boolean;

   error?: Error;

 }

 class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {

   public state: ErrorBoundaryState = {

     hasError: false

   };

   public static getDerivedStateFromError(error: Error): ErrorBoundaryState {

     return { hasError: true, error };

   }

   public componentDidCatch(error: Error, errorInfo: ErrorInfo) {

     console.error('Uncaught error:', error, errorInfo);

     // Log to error reporting service

   }

   public render() {

     if (this.state.hasError) {

       return this.props.fallback || (

         <div className="error-boundary">

           <h2>Something went wrong</h2>

           <p>{this.state.error?.message}</p>

           <button onClick={() => this.setState({ hasError: false })}>

             Try again

           </button>

         </div>

       );

     }

     return this.props.children;

   }

 }

 // Usage

 function App() {

   return (

     <ErrorBoundary fallback={<div>Oops! Something broke.</div>}>

       <MyComponent />

     </ErrorBoundary>

   );

 }

// Bad: Silent failure

 try { /* ... */ } catch { /* empty */ }

 // Good: At least log the error

 try { /* ... */ } catch (error) {

   console.error('Operation failed:', error);

 }

class NetworkError extends Error {

   constructor(public status: number, message: string) {

     super(message);

     this.name = 'NetworkError';

   }

 }

 class ValidationError extends Error {

   constructor(public field: string, message: string) {

     super(message);

     this.name = 'ValidationError';

   }

 }

// In a data access layer

 async function getUser(id: string): Promise {

   const response = await fetch(`/api/users/${id}`);

   if (!response.ok) {

     throw new NetworkError(response.status, 'Failed to fetch user');

   }

   return response.json();

 }

 // In a UI component

 async function loadUser() {

   try {

     const user = await getUser('123');

     setUser(user);

   } catch (error) {

     if (error instanceof NetworkError) {

       if (error.status === 404) {

         showError('User not found');

       } else {

         showError('Network error. Please try again later.');

       }

     } else {

       showError('An unexpected error occurred');

     }

   }

 }

