    });

    if (!response.ok) {

      throw new Error("HTTP error " + response.status);

    }

    const result = await response.json();

    document.getElementById("demo").textContent =

    result.message;

  }

  catch (error) {

    document.getElementById("demo").textContent =

    error.message;

  }

}

sendPerson();

